    "methods": {
      "checkAfterExecution(bytes32,bool)": {
        "details": "Called by the Safe after every execution. A no-op unless a genuine      Safe is calling; even then a module failure is a skipped sync.      A revert here would be fatal to the Safe, so the only statement in      reach that touches another contract is the low-level call, and its      result is ignored except for the event."
      },
      "checkTransaction(address,uint256,bytes,uint8,uint256,uint256,uint256,address,address,bytes,address)": {
        "details": "Deliberately empty: unnamed parameters so that nothing here can even      tempt a future edit into reading calldata, and no storage read. The      only reverts reachable through this function are the ABI decoder's,      which a genuine Safe never triggers."
      }
    },
